<script setup lang="ts">
import type { Prospect, ProspectSettings } from '~/types/prospecting'
import { contactCounted, responseCounted, interestCounted, segmentResults } from '~/utils/prospecting'
const props = defineProps<{ leads: Prospect[]; settings: ProspectSettings }>()
const results = computed(() => segmentResults(props.leads))
const funnel = computed(() => [{ name: 'Selecionadas', count: props.leads.length }, { name: 'Contatadas', count: props.leads.filter(contactCounted).length }, { name: 'Responderam', count: props.leads.filter(responseCounted).length }, { name: 'Interessadas', count: props.leads.filter(interestCounted).length }, { name: 'Fechadas', count: props.leads.filter(lead => lead.stage === 'Fechado').length }])
const contacted = computed(() => props.leads.filter(contactCounted).length)
const won = computed(() => props.leads.filter(lead => lead.stage === 'Fechado'))
const money = (value: number) => value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
</script>
<template>
  <div class="space-y-7"><div class="grid gap-6 lg:grid-cols-[1fr_1.2fr]"><section class="rounded-2xl border border-slate-200 bg-white p-6"><p class="text-xs uppercase tracking-widest text-slate-500">Da seleção à venda</p><h2 class="mt-3 text-xl font-semibold">Seu funil real</h2><div class="mt-7 space-y-5"><div v-for="item in funnel" :key="item.name"><div class="mb-2 flex justify-between text-sm"><span>{{ item.name }}</span><strong>{{ item.count }}</strong></div><div class="h-2 overflow-hidden rounded-full bg-slate-100"><div class="h-full rounded-full bg-[#2458df]" :style="{ width: `${leads.length ? item.count / leads.length * 100 : 0}%` }" /></div></div></div><p class="mt-6 text-xs leading-6 text-slate-500">Cada empresa conta uma vez em cada etapa alcançada. Respostas e interesses usam os registros do histórico, incluindo contatos arquivados.</p></section><section class="rounded-2xl bg-[#14243e] p-6 text-white"><p class="text-xs uppercase tracking-widest text-blue-200">Resultado financeiro registrado</p><h2 class="mt-3 text-xl font-semibold">Projeto e recorrência separados</h2><div class="mt-8 grid gap-7 sm:grid-cols-2"><div><p class="text-xs text-slate-300">Projetos fechados</p><p class="mt-2 text-3xl font-semibold">{{ money(won.reduce((sum, lead) => sum + lead.proposalValue, 0)) }}</p></div><div><p class="text-xs text-slate-300">Mensalidade contratada</p><p class="mt-2 text-3xl font-semibold">{{ money(won.reduce((sum, lead) => sum + lead.monthlyValue, 0)) }}</p></div><div><p class="text-xs text-slate-300">Investimento informado</p><p class="mt-2 text-2xl">{{ money(settings.budget) }}</p></div><div><p class="text-xs text-slate-300">Custo por empresa contatada</p><p class="mt-2 text-2xl">{{ contacted ? money(settings.budget / contacted) : '—' }}</p></div></div><p class="mt-8 border-t border-white/20 pt-5 text-xs leading-6 text-slate-300">Valores informados por você, sem confirmação de pagamento. Mensalidade não é somada ao valor dos projetos. Não há previsão automática de retorno.</p></section></div>
    <section class="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div class="p-6"><p class="text-xs uppercase tracking-widest text-slate-500">Aprenda antes de ampliar o investimento</p><h2 class="mt-3 text-xl font-semibold">Quais segmentos estão respondendo?</h2></div><div class="overflow-x-auto" tabindex="0" role="region" aria-label="Resultados por segmento"><table class="w-full min-w-[680px] text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="p-4" scope="col">Segmento</th><th class="p-4" scope="col">Contatadas</th><th class="p-4" scope="col">Respostas</th><th class="p-4" scope="col">Interessadas</th><th class="p-4" scope="col">Fechadas</th><th class="p-4" scope="col">Taxa de resposta</th></tr></thead><tbody><tr v-for="row in results" :key="row.segment" class="border-t border-slate-100"><th scope="row" class="p-4 font-medium">{{ row.segment }}</th><td class="p-4">{{ row.contacted }}</td><td class="p-4">{{ row.responses }}</td><td class="p-4">{{ row.interested }}</td><td class="p-4">{{ row.won }}</td><td class="p-4">{{ row.contacted ? `${row.rate}%` : '—' }}</td></tr></tbody></table></div><p v-if="!results.length" class="p-7 text-sm text-slate-500">Cadastre empresas e registre suas abordagens para comparar os segmentos.</p><p class="border-t p-5 text-xs leading-6 text-slate-500">Taxa de resposta = empresas que responderam ÷ empresas contatadas. Amostras pequenas servem como aprendizado, não como garantia de desempenho.</p></section></div>
</template>
